INSERT INTO breweries (name, description, country, website_url) VALUES
    ('月光醸造所',     '東京・奥多摩の山中に佇む小規模ブルワリー。月が美しい夜に仕込むという伝説を持つ。', 'JP', 'https://example.com/gekko'),
    ('霧の峠ビール',   '長野県の山間部で霧の多い気候を活かして醸造。フルーティなエールが看板。',           'JP', 'https://example.com/kirinotouge'),
    ('蒼海クラフト',   '横須賀の海辺に立つブルワリー。海風と潮の香りをインスパイアした作品を揃える。',   'JP', 'https://example.com/sokai'),
    ('暁ブルーイング', '大阪・天満橋の路地裏。夜明けをイメージした黄金色のエールで地元に愛される。',     'JP', 'https://example.com/akatsuki'),
    ('山伏醸造',       '山形県の出羽三山麓に位置し、雪解け水を仕込み水に使用した清冽なビールが特徴。',   'JP', 'https://example.com/yamabushi'),
    ('翠嵐ビール工房', '北海道・富良野の農場直結ブルワリー。自家栽培のホップと麦芽を惜しみなく使う。',   'JP', 'https://example.com/suiran'),
    ('紺碧エール',     '福岡・博多港に面した倉庫を改装したタップルームを持つ都市型ブルワリー。',           'JP', 'https://example.com/konpeki'),
    ('朱鷺ブルワリー', '新潟県佐渡島にある離島ブルワリー。佐渡金山の井戸水を仕込みに使用。',             'JP', 'https://example.com/toki'),
    ('銀杏クラフト',   '京都・西陣の町家をリノベした醸造所。伝統的な和の素材を取り入れた一期一会な醸造。', 'JP', 'https://example.com/icho'),
    ('凪醸造所',       '広島・呉の造船所跡地に建つ。穏やかな瀬戸内の海をコンセプトにした柔らかなビール。', 'JP', 'https://example.com/nagi');
INSERT INTO beers (brewery_id, name, style, abv, description) VALUES
INSERT INTO tasting_notes (beer_id, appearance, aroma, taste, overall, rated_at) VALUES
    (1,  '澄んだ黄金色、白く細かい泡が立つ',         'グレープフルーツと松ヤニのホップ香、背後に淡いモルトの甘み',   '最初にシトラスのフレッシュな苦み、中盤からモルトの甘みが追いかける。フィニッシュは爽やか', 5, '2026-03-01 12:00:00'),
    (1,  'クリアなアンバー、泡立ちは中程度',          '柑橘系の爽やかな香り、少し花のようなニュアンス',               'ドライホップの苦みが心地よい。後味に軽いキャラメル感が残る',                               4, '2026-03-15 18:00:00'),
    (2,  '完全な漆黒、タンのような厚い泡',            'ローストコーヒーとビターチョコ、わずかに焦がしモルト',          '重厚でクリーミー。コーヒーの苦みとチョコの甘みが長い余韻を作る',                           5, '2026-02-10 20:00:00'),
    (2,  '漆黒で光を通さない',                        'エスプレッソと黒糖の甘い香り',                                  'ドライでありながら甘みも感じる複雑な一杯。炭酸が少なめで飲みやすい',                       4, '2026-02-20 19:00:00'),
    (3,  '深いアンバーに近いゴールド',                'パインとパッションフルーツ、松ヤニのレジン感',                  '煌めくような苦みが最初から最後まで続く。トロピカルフルーツの甘みが苦みを包む',             5, '2026-01-20 21:00:00'),
    (3,  '濁りのあるオレンジがかったゴールド',        'マンゴーと南国フルーツの爆発的な香り',                          'ジューシーでありながら確かな苦み。ホップの存在感が全面に出る一杯',                         4, '2026-01-28 20:30:00'),
    (4,  '白く濁った薄黄色、泡がふわふわ',            'コリアンダーとオレンジピール、バナナのような酵母香',            '軽やかで柔らかい口当たり。フルーティで爽快、毎日飲めるホワイトエール',                     4, '2026-04-05 14:00:00'),
    (4,  '乳白色に近い白濁',                          '花と柑橘が混ざり合うフルーティな香り',                          'やや酸味があり爽やか。飲み口がすっきりしていて食事に合わせやすい',                         3, '2026-04-12 16:00:00'),
    (5,  '深いアンバー、赤みがかった色調',            '松ヤニとグレープフルーツ、奥にトロピカル感',                    '強烈なホップの苦みが最前面に。長い余韻とともにトロピカルフルーツが顔を出す',               5, '2026-02-05 22:00:00'),
    (5,  '濁りある褐色',                              'シトラスとマンゴー、レジンの力強い香り',                        '飲み込んだ後もホップの苦みが波のように押し寄せる。飲み疲れしないバランス',                 4, '2026-02-14 21:00:00'),
    (6,  'クリアな明るい黄金色',                      'フラワリーでハニーなホップ、淡いモルトの甘み',                  '軽快でバランスが良く、苦みと甘みが仲良く共存している。夏の昼間にぴったり',                 4, '2026-04-15 15:00:00'),
    (6,  '澄んだゴールド',                            'フローラルで爽やかな香り',                                      'クリーンな後味。日常飲みに向いた穏やかな一杯',                                             3, '2026-04-22 16:00:00'),
    (7,  '薄いゴールド、澄んでいる',                  '海の塩気を連想させるミネラル感、柑橘ホップの爽やかさ',          '潮風を感じるような軽快な飲み口。ホップと塩気が爽快感を倍増させる',                         4, '2026-03-05 18:00:00'),
    (7,  'クリアなペールゴールド',                    'フレッシュなホップと微かなミネラル',                            'スムーズで飲みやすい。後味にほのかな苦みと塩気が残る',                                     3, '2026-03-18 19:00:00'),
    (8,  '漆黒に近い深いブラウン',                    'ダークチョコとエスプレッソ、バニラのニュアンス',                '濃厚でリッチ。アルコール感はあるが温かみのある飲み口が長く続く',                           5, '2026-01-10 21:00:00'),
    (8,  '完全な黒',                                  '焦がしモルトとカカオ、わずかにスモーク',                        '重厚で複雑。この一杯で夜が完結する。余韻はいつまでも続く',                                 5, '2026-01-20 22:00:00'),
    (9,  'ヘイジーなオレンジゴールド',                '白桃と花、スパイスのような複雑な香り',                          'ドライでスパイシーなセゾン特有の飲み口。後半に酸味と塩気が顔を出す',                       4, '2026-03-08 12:30:00'),
    (9,  '薄く濁ったゴールド',                        'フルーティでハーブ的な香り',                                    'セゾン特有のドライな口当たり。爽快で個性的',                                               3, '2026-03-20 14:00:00'),
    (10, '明るい黄金色、澄んでいる',                  '蜂蜜とフローラルなホップ、穏やかな麦芽の甘み',                  '軽やかで飲みやすい。夜明けの一杯にふさわしい爽快感',                                       4, '2026-04-20 18:00:00'),
    (10, 'クリアなゴールド',                          'フレッシュなホップとモルトの甘い香り',                          'スムーズで優しい飲み口。苦みは控えめ',                                                     3, '2026-04-27 19:00:00'),
    (11, '深いアンバー',                              'グレープフルーツとパッションフルーツ、松脂のレジン感',          '苦みのインパクトが大きく、後から熱帯果実の甘みが追いかける',                               5, '2026-01-15 20:00:00'),
    (11, 'やや濁ったゴールド',                        'エキゾチックフルーツとパインの香り',                            '圧倒的なホップ存在感。フィニッシュは長くドライ',                                           5, '2026-01-25 21:30:00'),
    (12, '明るいオレンジがかったゴールド',            'バナナとクローブ、柑橘の酵母香',                                '茜色の空のような温かみ。甘みと酸味のバランスが取れた飲みやすさ',                           4, '2026-04-01 14:00:00'),
    (12, '薄いオレンジ',                              'フルーティな酵母香',                                            '軽やかな飲み口。ほのかな甘みが心地よい',                                                   3, '2026-04-08 15:00:00'),
    (13, 'クリアな薄い黄色',                          '山の清流を思わせる清潔感ある麦芽香',                            '雪解け水のように純粋でクリーン。キレがあり、食事の邪魔をしない',                           4, '2026-04-15 17:00:00'),
    (13, '澄んだ薄黄',                                '穀物の淡い香りと草のようなニュアンス',                          'のどごし重視のクリーンな飲み口。スッキリしていてゴクゴク飲める',                           3, '2026-04-22 18:00:00'),
    (14, '深いダークブラウン',                        'ロースト麦芽と焦がしビスケット、かすかに森の香り',              '山の険しさを表現するような力強いビター。後半に甘みが広がりバランスが整う',                 4, '2026-03-10 19:00:00'),
    (14, '赤みがかったブラウン',                      'トースティなモルト、黒糖のような甘み',                          'リッチで飲み応えがある。山岳修行のような力強さが心地よい疲労感を与える',                   4, '2026-03-22 20:00:00'),
    (15, '白く濁った薄黄色',                          'ふわりと小麦の甘い香り、背後に山百合のような花香',              '清らかで澄んだ飲み口。霊山の水を直接飲んでいるような清潔感がある',                         3, '2026-04-05 15:00:00'),
    (15, '乳白色がかった白濁',                        '穀物の甘みとかすかなフローラル',                                'まろやかで口当たりが柔らかい。すっきりした後味が長く続く',                                 4, '2026-04-12 16:00:00'),
    (16, 'ヘイジーなゴールド',                        '自家農場のホップのグリーンでフレッシュな香り',                  '大地の恵みを感じるナチュラルな風味。農場の朝の空気を飲んでいるよう',                       4, '2026-05-01 12:00:00'),
    (16, '薄く濁ったゴールド',                        'フレッシュなホップと穀物の甘い香り',                            'クリーンで飲みやすく、素直な味わい。農場直結ならではの新鮮さを感じる',                     3, '2026-05-08 14:00:00'),
    (17, '深いアンバー',                              '北海道産ホップのシトラスとレジン感',                            '広大な大地のようなスケール感がある苦み。後口にトロピカルフルーツが顔を出す',               5, '2026-04-20 16:00:00'),
    (17, 'クリアなアンバー',                          'グレープフルーツと松の香り',                                    '力強い苦みと長い余韻。北海道の夏の爽快さを感じる',                                         4, '2026-04-27 17:00:00'),
    (18, 'ヘイジーなピンクがかったゴールド',          'ラベンダーの花の香り、微かな塩気',                              '世界にひとつのラベンダーゴーゼ。フローラルな香りと塩気がユニークなバランスを作る',         5, '2026-05-05 13:00:00'),
    (18, '淡いピンク',                                '花畑を歩くようなラベンダーの甘い香り',                          '酸味と塩味のゴーゼらしさにラベンダーが加わり、ひと言では表せない複雑さ',                   4, '2026-05-12 14:00:00'),
    (19, '明るい薄いゴールド',                        '博多の夜の活気を連想させる軽やかなホップ香',                    '飲みやすく明るい飲み口。博多の人情のような親しみやすさがある一杯',                         3, '2026-03-15 19:00:00'),
    (19, 'クリアなゴールド',                          'フレッシュで爽やかなホップ',                                    'スムーズで親しみやすい。屋台で飲みたくなる一杯',                                           4, '2026-03-28 20:00:00'),
    (20, '明るいアンバー',                            'グレープフルーツとレジン、力強いホップ',                        '玄界灘の荒波のような力強い苦みと香り。フィニッシュは長くドライ',                           4, '2026-04-05 19:00:00'),
    (20, '深いアンバー',                              'ホップのレジン感とシトラス',                                    'ぐいっと来る苦みが心地よい。荒々しさの中に品がある',                                       5, '2026-04-12 20:00:00'),
    (21, 'ダークブラウン、タンの泡',                  'チョコレートとローストコーヒー、屋台の熱気',                    '博多屋台の賑わいを凝縮したポーター。甘みとビターのバランスが絶妙',                         4, '2026-04-20 21:00:00'),
    (21, '黒に近い褐色',                              'キャラメルとコーヒー、かすかにスモーク',                        'ほろ苦く深みのある一杯。屋台の夜はこれに限る',                                             4, '2026-04-27 22:00:00'),
    (22, '明るいゴールド、澄んでいる',                '蜂蜜と黄金色の麦芽の甘い香り',                                  '佐渡の清水とモルトが調和したゴールデンエール。シンプルだが奥深い',                         4, '2026-03-01 19:00:00'),
    (22, '薄いゴールド',                              '麦芽の甘みとフローラルなホップ',                                'すっきりした飲み口。島の空気を感じる清潔感がある',                                         3, '2026-03-10 20:00:00'),
    (23, 'ヘイジーなゴールド',                        '酵母のファンキーな香り、白桃と花のニュアンス',                  '孤島のセゾンらしく、自由奔放な飲み口。ドライでスパイシーな余韻が長い',                     4, '2026-04-01 18:00:00'),
    (23, '薄く濁ったゴールド',                        'フルーティな酵母香とかすかな酸味',                              '個性的な飲み口。離島の孤独と自由を同時に感じる一杯',                                       5, '2026-04-08 19:00:00'),
    (24, '淡いピンクがかったペールゴールド',          '赤シソと桃のような和のフルーティな香り',                        '朱鷺の羽のような淡い色合いと優雅な飲み口。エレガントで後口が爽やか',                       4, '2026-04-15 14:00:00'),
    (24, 'クリアなペールゴールド',                    'フルーティで繊細な香り',                                        'スムーズで軽やか。繊細な風味が和の世界観を表現している',                                   3, '2026-04-22 15:00:00'),
    (25, '赤みがかった深いアンバー',                  '西陣織のように複雑なカラメルとモルトの重なり',                  'リッチで深みがある。何層にも積み重なったモルトの風味が京都の歴史を連想させる',             4, '2026-03-15 12:00:00'),
    (25, '明るいアンバー',                            'トースティな麦芽とカラメルの甘み',                              'まろやかで飲み応え十分。工芸品を味わうような丁寧な一杯',                                   5, '2026-03-28 13:00:00'),
    (26, '漆黒、クリーミーな泡',                      '抹茶の渋みとロースト麦芽、ビターチョコ',                        '緑茶の渋みとスタウトの苦みが融合した唯一無二の一杯。京都らしい品格がある',                 5, '2026-04-05 20:00:00'),
    (26, '完全な黒',                                  '抹茶粉とエスプレッソの複雑な香り',                              '渋みと苦みと甘みが三位一体。宇治抹茶の上質さがビールに宿っている',                         5, '2026-04-12 21:00:00'),
    (27, '白く濁った薄黄色',                          '柚子と白胡麻の和のフレグランス、小麦の甘み',                    '鴨川沿いを歩くような軽やかさ。柚子の爽やかな酸味が後半に顔を出す',                         4, '2026-04-20 14:00:00'),
    (27, '乳白色',                                    '柚子とほのかなごまの香り',                                      'すっきりした和の風情。食中酒として最高のホワイトエール',                                   3, '2026-04-27 15:00:00'),
    (28, 'クリアな薄いゴールド',                      '瀬戸内の海のようなミネラルと麦芽の清潔感',                      '余計な装飾を排したシンプルな美しさ。どこまでも飲み続けられる凪のような一杯',               4, '2026-04-30 17:00:00'),
    (28, '澄んだゴールド',                            'クリーンな麦芽香',                                              '穏やかで飲みやすい。瀬戸内の静かな海を眺めながら飲みたい',                                 3, '2026-05-07 18:00:00'),
    (29, '漆黒',                                      '溶鉱炉を思わせるロースト香、ダークチョコとコーヒー',            '呉の造船所の力強さを体現した一杯。重厚だが意外な甘みが包み込む',                           5, '2026-05-03 20:00:00'),
    (29, '完全な黒',                                  '鉄のような力強さとカカオの甘み',                                '圧倒的な存在感。ゴクゴク飲むものではなく、じっくり向き合う一杯',                           4, '2026-05-10 21:00:00'),
    (30, 'オレンジがかったゴールド',                  'シトラスとトロピカルホップ、軽やかな麦芽の甘み',                '夕焼けの多島美のような華やかさ。セッションIPAとは思えないホップの存在感',                   4, '2026-05-14 16:00:00'),
    (30, '明るいアンバー',                            '柑橘とフローラルなホップ香',                                    '飲みやすくホップが楽しめる。夕日を見ながら飲みたい一杯',                                   4, '2026-05-17 17:00:00');
